<script setup lang="ts">import type{Run}from '../types/domain';import StatusBadge from './common/StatusBadge.vue';defineProps<{runs:Run[];modelValue:number}>();defineEmits(['update:modelValue']);</script><template><div class="run-select"><label>研究档案<select :value="modelValue" @change="$emit('update:modelValue',Number(($event.target as HTMLSelectElement).value))"><option v-for="r in runs" :value="r.id">#{{r.id}} {{r.name}}</option></select></label><StatusBadge v-if="runs.find(r=>r.id===modelValue)" :status="runs.find(r=>r.id===modelValue)!.status"/></div></template>
